import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    processed_data = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            processed_data[k] = float(v * 2)
        elif isinstance(v, list):
            processed_data[k] = [float(x * 2) if isinstance(x, (int, float)) else x for x in v]
        elif isinstance(v, str):
            processed_data[k] = re.sub(r'\d+\.?\d*', lambda m: str(float(m.group()) * 2), v)
        else:
            processed_data[k] = v

    return pd.DataFrame([processed_data])

